"""Execute bounded UUX native fixtures with every update-process boundary wrapped."""
import argparse,hashlib,json,os,subprocess,uuid
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--repository',type=Path,required=True);p.add_argument('--executable',type=Path,required=True);p.add_argument('--fixtures',type=Path,required=True);p.add_argument('--kind',choices=['paths','host_process','dispatch'],required=True);p.add_argument('--work',type=Path,required=True);a=p.parse_args();r=a.repository.resolve();parent=a.work.resolve();assert parent.is_relative_to(r/'temp/test-work');parent.mkdir(parents=True,exist_ok=True);out=parent/(a.kind+'-'+uuid.uuid4().hex);out.mkdir();tmp=out/'tmp';tmp.mkdir();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();symbols=subprocess.run(['nm','--defined-only',a.executable],capture_output=True,text=True,check=True).stdout;definitions={x.split()[-1] for x in symbols.splitlines() if x.split()};boundaries=['fork','system','exit','waitpid','clock_gettime','usleep'];assert {'__wrap_'+x for x in boundaries}<=definitions;undefined=subprocess.run(['nm','--undefined-only',a.executable],capture_output=True,text=True,check=True).stdout;assert not set(boundaries)&{x.split()[-1].split('@')[0] for x in undefined.splitlines() if x.split()};(out/'undefined-symbols.txt').write_text(undefined);data=a.fixtures.read_text();counts={'paths':3072,'host_process':3672,'dispatch':1728};assert len(data.splitlines())==counts[a.kind];command=[str(a.executable.resolve())]
if a.kind=='dispatch':
 missing=out/'missing';present=out/'present.bin';directory=out/'archive-directory';present.write_bytes(b'input-existence fixture, not firmware');directory.mkdir();command += list(map(str,[missing,present,directory]))
env={**os.environ,'TMPDIR':str(tmp),'TMP':str(tmp),'TEMP':str(tmp),'ASAN_OPTIONS':'detect_leaks=1:halt_on_error=1','UBSAN_OPTIONS':'halt_on_error=1'};(out/'command.json').write_text(json.dumps(command,indent=2)+'\n');v=subprocess.run(command,input=data,capture_output=True,text=True,env=env,cwd=r);(out/'native.stdout').write_text(v.stdout);(out/'native.stderr').write_text(v.stderr);assert v.returncode==0,v.stderr;expected={'paths':'PASS original_path_cases=3072\n','host_process':'PASS original_host_process_cases=3672 explicit_source_port_error_cases=9\n','dispatch':'PASS original_composed_dispatch_cases=1728\n'}[a.kind];assert (v.stderr if a.kind=='dispatch' else v.stdout)==expected;proof={'passed':True,'kind':a.kind,'original_observations':counts[a.kind],'executable_sha256':sha(a.executable),'fixture_sha256':sha(a.fixtures),'stdout_sha256':sha(out/'native.stdout'),'stderr_sha256':sha(out/'native.stderr'),'all6OSsymbols_linkwrapped_no_direct_import':True,'no_real_update_process_or_sleep_or_device_execution':True};(out/'validation.json').write_text(json.dumps(proof,indent=2)+'\n');print(expected.strip())
